import * as T from '../vendor/three.module.min.js';
import {seeded} from './math.js';
export function createEffects(scene){const parts=[],rnd=seeded(89);return {burst(x,y,z,color=0xffd077){for(let i=0;i<9;i++){const m=new T.Mesh(new T.SphereGeometry(.1,4,3),new T.MeshBasicMaterial({color}));m.position.set(x,y,z);scene.add(m);parts.push({m,ttl:.6,vx:(rnd()-.5)*10,vy:rnd()*7,vz:(rnd()-.5)*10});}},trace(a,b){const geo=new T.BufferGeometry().setFromPoints([a,b]);const m=new T.Line(geo,new T.LineBasicMaterial({color:0xffe4a0}));scene.add(m);parts.push({m,ttl:.1,vx:0,vy:0,vz:0});},update(dt){for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.ttl-=dt;p.m.position.x+=p.vx*dt;p.m.position.y+=p.vy*dt;p.m.position.z+=p.vz*dt;p.vy-=8*dt;if(p.ttl<=0){scene.remove(p.m);p.m.geometry.dispose();p.m.material.dispose();parts.splice(i,1);}}}};}
